"""Pinned certificate fingerprint store for Tessaro feeds."""

import json
import os


class PinStore:
    """Store of pinned certificate fingerprints by hostname."""

    def __init__(self, pins: dict):
        """Initialize with a dict mapping hostnames to sets of fingerprint hex strings."""
        self._pins = {host: set(fps) for host, fps in pins.items()}

    @classmethod
    def load(cls) -> "PinStore":
        """Load the pin store from the package's pinned certificates data."""
        data_path = os.path.join(os.path.dirname(__file__), "pins.json")
        with open(data_path, "r") as f:
            pins = json.load(f)
        return cls(pins)

    def matches(self, host: str, fp: str) -> bool:
        """Return True if the fingerprint matches any pinned certificate for the host."""
        host_pins = self._pins.get(host)
        if host_pins is None:
            return False
        return fp in host_pins
